import{_ as t}from"./chunks/25d4230f38b31b3c495f.Bt2AXpTK.js";import{_ as o,o as i,c as r,a6 as a}from"./chunks/framework.CnPv4DE1.js";const m=JSON.parse('{"title":"Learn This Skill If You Want To Thrive The Next 10 Years","description":"","frontmatter":{"title":"Learn This Skill If You Want To Thrive The Next 10 Years","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/learn-this-skill-if-you-want-to-survive-the-next-10-years.md","filePath":"en/letters/learn-this-skill-if-you-want-to-survive-the-next-10-years.md"}'),n={name:"en/letters/learn-this-skill-if-you-want-to-survive-the-next-10-years.md"};function s(l,e,p,h,u,c){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="learn-this-skill-if-you-want-to-thrive-the-next-10-years" tabindex="-1">Learn This Skill If You Want To Thrive The Next 10 Years <a class="header-anchor" href="#learn-this-skill-if-you-want-to-thrive-the-next-10-years" aria-label="Permalink to &quot;Learn This Skill If You Want To Thrive The Next 10 Years&quot;">​</a></h1><p>Dan Koe · 2024-01-19 · <a href="https://thedankoe.com/letters/learn-this-skill-if-you-want-to-survive-the-next-10-years/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/learn-this-skill-if-you-want-to-survive-the-next-10-years">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/_VLZ4b9LHLs?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>Ever since I can remember, I’ve had the goal of doing what I love for a living. Isn’t that what everyone wants?</p><p>My family, teachers, and even the people I was following online screamed at me to go down other paths.</p><p>So that’s what I did.</p><ul><li>Went to college (and didn’t finish after 5 years)</li><li>Learned creative skills on the side</li><li>Started every online business imaginable</li><li>Learned to code because it was “lucrative”</li><li>Dropped out of college because it was wasting my time</li><li>Got a $55K/year job as an entry level web developer at a design agency</li></ul><p>Throughout this entire journey, my dream of “doing what I love” stuck in the back of my head. I was constantly reminded of it. There wasn’t a single moment from age 16-25 where I wasn’t working on a meaningful side project.</p><p>I still maintain this habit to this day. If it isn’t a business project, it’s a health project.</p><p>This is how I get out of a rut, because the only reason I fall into a rut is psychic entropy, the mind tending toward disorder. Meaning I don’t have a goal, project, or priority to bring my focus to.</p><p>My current projects are Kortex (second brain software), Kortex University (a school for creators), promoting my book, planning another book (to write in Kortex), and gaining a few more pounds before I trim down for the warm seasons.</p><p>Why am I telling you all of this?</p><p>Because I realized most people didn’t know what they were talking about.</p><p>I was taking career and life advice from people who hadn’t achieved what I wanted to achieve. In their closed mind, the reality I wanted to create was impossible, yet I kept looping back to projects that I loved working on for the sake of maintaining my sanity.</p><p>Most people don’t have a personal project that will create the future they want.</p><p>Most people don’t realize a personal project is not optional to <em>create</em> the future <em>they</em> want.</p><p>The only other option is to live by your programming, pursue the goals that society set for you, and work on the projects that lead to those goals. If you don’t spend 1 hour building your dreams, you will spend 8 hours building someone else’s, for life.</p><p>10 years ago, my mindset was: <em>“If I can monetize any of these passion projects, I’ll be set. All I need to do is learn and build until one works. I need to increase my capacity for luck with skill acquisition and experience. It may take 10 years, but some people go to school for 12. Even if I fail I’d be in a similar position.”</em></p><p>After years of trial and error with every “marketable skill” that people tell you to learn, I found the secret.</p><p>Well, not really a secret, but I’m supposed to make you curious to read more ya know.</p><p>Before we begin:</p><p>This one is going to be long. Make sure you have the bandwidth and time to read it. I promise it will be worth it.</p><p>If you want to learn the ins and outs of writing (that can’t be covered in one article), check out <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2-Hour Writer.</a></p><h2 id="why-writing" tabindex="-1">Why Writing? <a class="header-anchor" href="#why-writing" aria-label="Permalink to &quot;Why Writing?&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>The future of media is decentralized.</p><p>People are and will continue to turn to:</p><ul><li>Social media for news</li><li>Courses for education</li><li>Creators for knowledge</li></ul><p>I don’t want to hear about AI disrupting writing.</p><p>I see it as an impossibility that the only thing we consume online is created by a robot without a soul.</p><p>The emergence of AI seems to favor human creativity, and media is the vessel for front-end creativity.</p><p>AI is a tool for writers to become more prolific.</p><p>Writing is the skill that breathes life into any other skill you learn.</p><p>It is <em>the</em> meta-skill that people avoid learning until they are forced to (because they need to survive).</p><p>They don’t see it’s importance because it’s <em>“just plain old writing, who needs to learn that?”</em></p><p>There was a reason I failed at almost every business model I tried.</p><p>Digital art, SEO, Facebook ads, dropshipping, e-commerce stores, and more.</p><p>I was so focused on learning the skill and building a website that I forgot I actually had to get customers at some point.</p><p>How do you get customers?</p><p>Writing.</p><p>Content (or media) is the front end of the internet. It’s how you capture, hold, and convert attention in a sea of self-deprecating memes and valueless content.</p><p>The foundation of content is writing.</p><ul><li><strong>Tweets?</strong> Writing.</li><li><strong>Threads?</strong> Writing.</li><li><strong>Newsletters?</strong> Writing.</li><li><strong>Blog posts?</strong> Writing.</li><li><strong>Cold emails?</strong> Writing.</li><li><strong>Social media captions?</strong> Writing.</li><li><strong>Landing pages?</strong> Writing.</li><li><strong>Product descriptions?</strong> Writing.</li><li><strong>Course modules?</strong> Writing.</li><li><strong>Client communications?</strong> Writing.</li><li><strong>Customer resources?</strong> Writing.</li><li><strong>Ads of any form?</strong> Starts with writing.</li><li><strong>YouTube videos?</strong> Done best with written scripts.</li><li><strong>Instagram reels and TikToks?</strong> Like reading well-written tweets.</li><li><strong>Images on Instagram?</strong> Usually designed from a well-written quote or saying.</li><li><strong>Any other form of online marketing, advertising, or entertainment?</strong> Starts with writing.</li></ul><p><em>Everything that your audience, customers, and network see starts with writing.</em></p><p>Don’t underestimate that power.</p><p>Every single person in business is a writer at their core, they just don’t label themselves as that.</p><p>There’s a reason I can outperform every dude with six pack abs in terms of engagement and follower growth on Instagram.</p><p>High-impact digital writing.</p><p>Not technical or academic writing.</p><p>I’m not here to teach you how to write a research paper. I’m here to teach you how to write in a way that lets you live the life you want.</p><p>If you want to become a master of content (and leverage no-code tools to distribute your writing and attract an audience) it’s pretty clear that writing needs to be the foundation of your one-person business.</p><h3 id="_6-steps-to-starting-a-one-person-writing-business" tabindex="-1">6 Steps To Starting A One-Person Writing Business <a class="header-anchor" href="#_6-steps-to-starting-a-one-person-writing-business" aria-label="Permalink to &quot;6 Steps To Starting A One-Person Writing Business&quot;">​</a></h3><blockquote><p>Content is an extension of the personal and collective mind. We put out our ideas, beliefs, and opinions that form a digital society, cultures, and world. Content on the internet is content in the collective consciousness.</p><p>The Art Of Focus</p></blockquote><p>I call myself a writer because that is what I do on a daily basis (even when it doesn’t seem like it on social media).</p><p>I’ve sustained a $100K-$250K per month (with the occasional jump to $500K-$700K) revenue by writing tweets, newsletters, and threads that get repurposed into Instagram posts, YouTube videos, LinkedIn posts, and the rest. This is only for my personal brand, not my other company.</p><p>In reflection, and referring to the top of this letter, writing is the force multiplier that made me have to pay 20x my previous web design salary in taxes each year. That’s a solid problem to have.</p><p>But, if you were to strip things down to only X and a Newsletter, I would still maintain a lot of that revenue.</p><p>Don’t fall into the trap that you have to have an insane follower count across all platforms to replace your current income. <a href="/letters/the-7-digital-career-paths-from-zero-experience-to-advanced">Follow this progression of income sources</a> if you don’t know where to start (last week’s letter).</p><p>Getting into it, here are the 6 steps to start your writing business.</p><p><strong>1) Choose A Topic You Can’t Shutup About</strong></p><p>Don’t overthink this just yet. Pick a topic and practice writing.</p><p>It can be productivity, creativity, spirituality, fitness, or any of the interests you could hold a conversation with.</p><p>If you are already writing, use one of your topics from <a href="/letters/dont-get-replaced-by-ai-how-to-write-authentic-content">your topic tree</a>.</p><p><strong>2) Brainstorm Your Unique Perspective</strong></p><p>Forget everything you know about “value.”</p><p>Actionable advice and platitudes don’t sell as well as they did when the internet was just budding.</p><p>Novelty catches attention. Attention is a given if you want people to read what you write.</p><p>Novel perspectives are the best (and replicable way) to capture attention without using sleazy tactics.</p><p>How do you come up with a novel perspective?</p><p>Braindump:</p><ul><li>Common problems associated with the topic</li><li>Benefits to overcoming those problems</li><li>Common goals associated with the topic</li><li>Roadblocks to achieving those goals</li><li>Personal experiences you’ve had</li></ul><p>Now, piece everything together and <em>explain it how you would if you were talking to a friend.</em></p><p>Don’t try to copy someones perspective or way of wording things. Say it in your own voice and let it <em>refine with time, effort, and practice.</em></p><p><strong>3) Write 500-1000 Words On The Topic Per Week</strong></p><p>You need a balance of depth and growth.</p><p>Meaning, you need long form and short form.</p><p>I’m big on starting a newsletter as your long form – but that can wait at the start.</p><p>Focus on a platform like X.</p><p>Write threads as your long form once a week.</p><p>Write 2-3 posts a day.</p><p>Then focus on step 5 the most for growth.</p><p>I will break down how to write these soon.</p><p><strong>4) Deconstruct &amp; Simplify Ideas For Daily Posts</strong></p><p>Writing long-form gives you multiple ideas to pull from.</p><p>Don’t try to copy-paste posts from your newsletters or threads – <em>rewrite them as standalone short posts.</em></p><p>We will discuss this throughout the letter.</p><p><strong>5) Learn How To Get Your Writing Shared (Crucial)</strong></p><p>Your writing means nothing if nobody sees it.</p><p>This is a huge beginner trap.</p><p>They think they can write all day and hope that our lord and savior the algorithm will make them an overnight success.</p><p>No. Writing is 20% of the equation. Traffic is 80%.</p><p>You get traffic on your profile and writing through replies, networking, and shares.</p><p>I break down every possible way to do this in the <a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">How To Actually Grow On Social Media letter.</a></p><p><strong>6) Monetize Your Experience</strong></p><p>Now that you have writing, a growing audience, and traffic – the only thing left to do is create a product or service to monetize.</p><p>We discussed all possible options in last weeks letter.</p><h2 id="everything-you-need-to-know-about-high-impact-writing" tabindex="-1">Everything You Need To Know About High-Impact Writing <a class="header-anchor" href="#everything-you-need-to-know-about-high-impact-writing" aria-label="Permalink to &quot;Everything You Need To Know About High-Impact Writing&quot;">​</a></h2><blockquote><p>Writing is the vehicle for articulated thought and communication. It is the medium for putting your message in front of those that can adopt the perspective it presents and operate within that shared reality.</p><p>The Art Of Focus</p></blockquote><p>There are a lot of writing frameworks out there.</p><p>After trying them all and making connections between them — I’ve created my own that I see as most effective.</p><p>If you want to read up on solid writing frameworks and connect the dots for yourself, some of my favorites are:</p><p><a href="https://goinswriter.com/better-sales-copy/" target="_blank" rel="noreferrer">PASTOR</a> — for longer-form writing that works well for persuasive blogs and sales pages.</p><p><a href="https://www.siegemedia.com/creation/aida-model" target="_blank" rel="noreferrer">AIDA</a> — a basic framework for shorter-form writing like tweets, email opt-in pages, and sometimes a general structure for long-form content.</p><p><a href="https://www.copywritematters.com/paso-copywriting-formula/" target="_blank" rel="noreferrer">PAS(O)</a> — great for any type of content writing, short or long form.</p><p>ALL of these follow a general storytelling structure that sparks curiosity:</p><ul><li><strong>A problem is introduced or implied</strong> — making people curious about what caused that problem (the law of cause and effect). Hint at the effect and THEN dive into the cause.</li><li><strong>It exposes people to a potential sequence of events</strong> — this is similar, but makes people want to understand the sequence of events that lead to a particular resolution (happy ending of a story).</li><li><strong>It creates an information gap</strong> — implying that there is educational, entertaining, or inspiring information that the specific reader desires.</li></ul><p>Once curiosity is sparked, you must deliver on your promises through:</p><ul><li>Personal, client, or other experiences that state or imply a transformation. A before (the problem) and an after (the resolution and associated benefits).</li><li>Step-by-step advice on how to get to the resolution quicker (a unique solution).</li><li>A crystal clear call to action to lead them deeper into your other content or spark behavior change — again, so they can associate that good behavior with you.</li></ul><p>You do not have to use my framework. You can use any that you’d like. But I have considered these aspects of curiosity and storytelling when crafting my own.</p><p>I call mine the <strong>APAG framework.</strong></p><p>Attention, Perspective, Advantage, and Gamify.</p><p>All are backed by psychological research with the intention of kicking someone into a flow-like experience… making them associate that good experience with you.</p><p>What can this be used for?</p><ul><li>Your newsletter</li><li>Podcast or YouTube scripts</li><li>Multiple threads or medium-form posts</li><li>Sales pages, landing pages, or opt-in pages</li><li>Book or eBook chapters or sections</li><li>Course modules, lead magnet modules, and other education</li><li>Potential ideas for tweets or short-form posts</li><li>Anything else that you use to build your business</li></ul><p>This section of the letter is pulled from <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer.</a></p><h3 id="attention-—-the-art-of-hooks-and-headlines" tabindex="-1">Attention — The Art Of Hooks And Headlines <a class="header-anchor" href="#attention-—-the-art-of-hooks-and-headlines" aria-label="Permalink to &quot;Attention — The Art Of Hooks And Headlines&quot;">​</a></h3><p>Your hook or headline are the most important aspect of your content.</p><p>If the hook doesn’t catch their attention — are they going to read the rest of the content that you put a lot of effort into? Or will they scroll past leaving your hard work gone unnoticed?</p><p>These are the 3 things that will make them continue reading:</p><ul><li><strong>Relevance</strong> — how relevant is it to their everyday life? Resolved pains or potential benefits. What’s in it for the reader?</li><li><strong>Awareness</strong> — is it simple or complex enough for the level of awareness you are targeting? Will they understand what you are about to show them?</li><li><strong>Effort</strong> — how fast will they receive the result (education, entertainment, or inspiration) and is it easy to get?</li></ul><p>These do not all have to be included in your headline or hook — but they should all be considered. The most potent ones should be used.</p><p>In a newsletter or article headline, you have much less room than a hook in a thread or other medium-form post (like a LinkedIn post).</p><p>Now, we can start to piece together our headline or hook with pieces of our outline and article (the problems, benefits, experiences, etc).</p><ul><li><strong>The BIG problem</strong> — you can create this by summarizing all of the problems you have listed.</li><li><strong>The BIG benefit</strong> — again, you can create this by summarizing all of the benefits into one.</li><li><strong>The BIG idea</strong> — can you summarize the most impactful parts of the post into one sentence?</li><li><strong>The transformation process</strong> — you can use numbers or a unique name to hint at the process that will get them results (posing an information gap).</li><li><strong>Timeframe</strong> — can you quantify a timeframe for how long it will take them to read the content or get the result you are promising? Use numbers.</li><li><strong>Negative personal experience</strong> — if you include a personal experience in your content, can you imply a low point during that experience and the emotion associated with it?</li></ul><p>Treat all of these as building blocks for the perfect hook.</p><p>You don’t have to include all of them, especially in the headline.</p><p>But the hook (the few starting lines of your content) can talk about them to grab the readers attention once they click to read.</p><p>Here is an example of a tweet with a short hook, can you see how it implies a problem, benefit, and transformation in one sentence?</p><blockquote><p>You won’t make it without obsession.\\</p><p>But nobody starts out obsessed. They start out curious. They experiment. They build things. They break things, They fail. And eventually they can’t pull themselves away.\\</p><p>Curiosity turns into obsession with time and persistence.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1728068209075519958?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 24, 2023</a></p></blockquote><p><strong>Note:</strong></p><p>The “attention” part of the APAG framework can be used for the hook or headline of long or short form.</p><p>Meaning, it can be used as the first slide of a carousel, first line of a tweet, the hook of a thread, etc.</p><p>All of the other pieces below will be treated as sections of long form, or they can individually be used for a short post like a tweet.</p><p>Long form should follow APAG.</p><p>Short form should be A+P, A+A, or A+G.</p><p>If you can fit them all in one short post, even better, try it.</p><h3 id="perspective-—-paint-a-picture-of-the-enemy-or-why-a-perspective-is-wrong" tabindex="-1">Perspective — Paint A Picture Of The Enemy Or Why A Perspective Is Wrong <a class="header-anchor" href="#perspective-—-paint-a-picture-of-the-enemy-or-why-a-perspective-is-wrong" aria-label="Permalink to &quot;Perspective — Paint A Picture Of The Enemy Or Why A Perspective Is Wrong&quot;">​</a></h3><p>This is where you relate to and amplify the problems that the reader is currently experiencing. This is also where you create the “enemy” of your story.</p><p>The best way you can do this is to paint a picture of a common perspective on the topic you are writing about.</p><p><em>Place a heavy emphasis on the problems associated with that perspective and the pains they cause.</em></p><p><em>This can be stated directly or implied. Here is an example tweet that paints a perspective without directly stating the problem:</em></p><blockquote><p>Wake up.<br> Hit snooze 4 times.<br> Stare at your phone.<br> Roll out of bed.<br> Make coffee.<br> Sit in traffic.<br> 8 hours of unfulfilling work.<br> Sit in traffic… again.<br> Argue with your &quot;significant&quot; other.<br> Walk the pet.<br> Watch TV.<br> Pass out.<br> Repeat.\\</p><p>This should scare the shit out of you.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1628758834192736256?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">February 23, 2023</a></p></blockquote><p>For more firepower, relate to them with a personal experience you’ve had with that perspective.</p><p>This is how I start most of my articles, newsletters, videos, and threads. I give a personal experience to help illustrate the problem and relate to the readers.</p><p>People want to feel understood. If they feel understood, they are more open to hearing what you have to say.</p><p><strong>Not sure what to say in this section?</strong></p><p>Good writing is about piecing together everything you have available to you.</p><p>For Perspective, you can use:</p><ul><li>Problems</li><li>Benefits</li><li>Examples</li><li>Metaphors</li><li>Quotes or Tweets</li><li>Personal or popular stories</li><li>Comparisons</li><li>Concepts</li></ul><p><em>Any of those elements (what we call them in Kortex) can be used as a start, transition, or end of a section.</em></p><p>If you have writers block, research or think of problems, examples, tweets, comparisons, etc.</p><h3 id="advantage-—-paint-a-picture-of-the-hero-vision-or-why-your-perspective-is-right" tabindex="-1">Advantage — Paint A Picture Of The Hero, Vision, Or Why Your Perspective Is Right <a class="header-anchor" href="#advantage-—-paint-a-picture-of-the-hero-vision-or-why-your-perspective-is-right" aria-label="Permalink to &quot;Advantage — Paint A Picture Of The Hero, Vision, Or Why Your Perspective Is Right&quot;">​</a></h3><p>Note that any part of the APAG framework can be a single line or an entire section of content.</p><p>As long as you hit on each part, you’re fine. If you can’t think of anything more to write, move on to the next part.</p><p>With persuasive writing, you are presenting a credible argument to sell something.</p><p>YOU are always selling, or at least you should be.</p><p>Not only selling products — but selling ideas and better ways of doing things. That’s what people want. Sell people out of a low-consciousness existence.</p><p>Now that you’ve painted a picture of their faulty perspective and the problems associated with it — you can start to shift they perspective to view things the way you do.</p><ul><li>How can you educate people to the point of understanding your perspective?</li><li>What do they need to know in order to understand where you are now?</li><li>What is missing from your writing that prevents them from understanding your better way of doing things?</li></ul><p>This is where you can present novel ideas, concepts, social proof, and experiences that make your argument credible.</p><p>If you have quotes, tweets, or other references you can include — that will only make your argument more credible.</p><p>Here is an example of an “Advantage” tweet I wrote:</p><blockquote><p>Writing is a great skill to learn because it pairs with any other skill or interests.\\</p><p>If you can write, you can do whatever you want and distribute the value you discover from those pursuits.\\</p><p>Writing allows you to make a living from living. The problem is that most people arent</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1656228093453914112?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 10, 2023</a></p></blockquote><p>This is the turning point in this metaphorical story. You are showing them a better way of doing things.</p><p>Again, you can use examples, problems, benefits, stories, metaphors, quotes, tweets, etc to help structure your argument and make it more credible.</p><h3 id="gamify-—-create-a-hierarchy-of-challenging-goals" tabindex="-1">Gamify — Create A Hierarchy Of Challenging Goals <a class="header-anchor" href="#gamify-—-create-a-hierarchy-of-challenging-goals" aria-label="Permalink to &quot;Gamify — Create A Hierarchy Of Challenging Goals&quot;">​</a></h3><p>When you think of a game, you think of a set hierarchy of goals (or quests, missions, etc) that give people clarity on what to do.</p><p>When done correctly, and when you give people a challenge that matches their skill, you put your readers into a flow state of discovering novel ideas that aid in their future.</p><p>In short, you “gamify” by giving step-by-step advice on how to achieve the transformation you’ve described in the post. (From old problem-ridden perspective to an advantageous perspective).</p><p>You are wrapping everything up into a clear, concise, and actionable way of getting a specific result — and making it clear on what they should do next.</p><p>What are the steps (or advice) that will help them overcome the problem you mentioned in “Perspective?”</p><p>What can they implement right now that will get them results?</p><p>List of steps, key points, or other things like a list of books to read that helps them solve the problem.</p><p>Here is a unique example of a “Gamify” tweet I wrote – this turned into a daily routine newsletter, and could easily be turned into key points for a thread:</p><blockquote><p>You need 4 habits:\\</p><p>One that builds your mind.<br> One that builds your body.<br> One that builds your business.<br> One that builds your relationships.\\</p><p>The good life is the process of becoming everything you could be.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1723689606774706247?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 12, 2023</a></p></blockquote><p><strong>If This Doesn’t Make Sense Yet (It Won’t)</strong></p><p>You will have to understand and internalize the structure of most long form content online.</p><p>You will also have to understand storytelling. They both interconnect.</p><p>Here is the general persuasive writing structure:</p><ul><li><strong>Hook</strong> — we’ve talked about this.</li><li><strong>Lead</strong> — introducing and agitating the problem</li><li><strong>Body</strong> — key points (numbered or not) separated by headlines to help learn and understand the topic</li><li><strong>Conclusion</strong> — a summary or step-by-step advice to overcoming the problem</li><li><strong>CTA</strong> — a call to action to do something next (not necessary on short posts)</li></ul><p>This IS a storytelling structure.</p><p>Storytelling is NOT always a story.</p><p>Stories consist of anecdotes, research, examples, metaphors, quotes, tweets, videos, other content, and anything else you can do to help someone else understand.</p><p>This is why it’s important to have a second brain (like <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>) filled with ideas you collect. Writing becomes so easy as it grows. You just piece ideas together in infinite ways.</p><p>You present a problem and guide someone to overcome it.</p><h2 id="the-key-to-short-writing" tabindex="-1">The Key To Short Writing <a class="header-anchor" href="#the-key-to-short-writing" aria-label="Permalink to &quot;The Key To Short Writing&quot;">​</a></h2><p>All of the above can be used to write short posts like tweets, IG posts, LinkedIn posts, reels scripts, and more.</p><p>But how do you get better at writing them?</p><p>Emulation.</p><p>I learned to write good tweets through observation.</p><p>Since you have ideas flowing from your other writing, take those ideas and:</p><ul><li>Study quotes from your favorite authors</li><li>Use tools like Twemex to research high performing posts (link)</li><li>Be a researcher not a consumer – read social media content to study other’s post structures</li><li>For every post you see, try to recreate it with your own ideas to train your mind to write like that</li></ul><p><em>Drown yourself in good short form writing.</em></p><p><em>Use their sentence structure as training wheels to write your own.</em></p><p><em>Contemplate why that writing does well. How does it make you feel? Why does it make you feel that way?</em></p><p>I’ve written an entire letter on <a href="/letters/dont-get-replaced-by-ai-how-to-write-authentic-content">how to write short-form content here</a>.</p><p>You can also download some of my best tweets and use them as training wheels for your content <a href="https://www.dropbox.com/scl/fi/nhvzkqzbzlp6ro6ocb8a4/ContentPresentation.pdf?rlkey=8kpb8t3wgc21wu9acqg33c80v&amp;dl=0" target="_blank" rel="noreferrer">in this PDF.</a></p><p>All of this takes practice, a lot of practice.</p><p>But if you want to earn an income from any other skill you have, you have to pair it with the skill of writing.</p><p>Thank you for reading, I hope it helped.</p><p>Dan</p>',201)])])}const y=o(n,[["render",s]]);export{m as __pageData,y as default};
